-- The date a person is retired from; null when they are not retired. A person with a date set is
-- retired at once, whatever the date. No claim of theirs may be dated after it.
ALTER TABLE person ADD COLUMN retired_from DATE;
# Retire the person from a date: no claim of theirs may be dated after it.
validate:
  class: net.officefloor.hq.app.person.ValidateRetire
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: retire
retire:
  class: net.officefloor.hq.app.person.RetirePerson
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

/** Retires the person from the date (the sheet's today when blank). Their claims keep counting. */
public class RetirePerson {
